def compute(vars):
    salaries = [vars["v1"], vars["v2"], vars["v3"], vars["v4"], vars["v5"]]
    total_salary = sum(salaries)
    average_salary = total_salary / len(salaries)

    return {
        "value": average_salary,
        "trace": {
            "salaries": salaries,
            "total_salary": total_salary,
            "count": len(salaries),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
